-- ============================================================================
-- MIGRACIÓN COMPLETA DE MYSQL A NEON (POSTGRESQL)
-- Proyecto: Lizdy Pineda Fotoestudio (liz-fotoestudio-app)
-- Incluye: Estructura de 8 tablas + Todos los datos reales + Secuencias e Índices
-- ============================================================================

BEGIN;

-- Limpiar tablas si existen previamente (en orden inverso de dependencias)
DROP TABLE IF EXISTS sesion_productos CASCADE;
DROP TABLE IF EXISTS sesion_fotos CASCADE;
DROP TABLE IF EXISTS ingresos CASCADE;
DROP TABLE IF EXISTS facturas CASCADE;
DROP TABLE IF EXISTS sesiones CASCADE;
DROP TABLE IF EXISTS citas CASCADE;
DROP TABLE IF EXISTS productos CASCADE;
DROP TABLE IF EXISTS clientes CASCADE;
DROP TABLE IF EXISTS usuarios CASCADE;

-- 1. Tabla: usuarios
CREATE TABLE usuarios (
  id SERIAL PRIMARY KEY,
  nombre VARCHAR(150) NOT NULL,
  email VARCHAR(200) NOT NULL UNIQUE,
  password VARCHAR(255) NOT NULL,
  rol VARCHAR(20) DEFAULT 'usuario' CHECK (rol IN ('admin', 'usuario')),
  foto_perfil VARCHAR(300) DEFAULT NULL,
  fecha_registro TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- 2. Tabla: clientes
CREATE TABLE clientes (
  id SERIAL PRIMARY KEY,
  nombre VARCHAR(150) NOT NULL,
  apellido VARCHAR(150) NOT NULL DEFAULT '',
  telefono VARCHAR(30) DEFAULT NULL,
  email VARCHAR(200) DEFAULT NULL,
  direccion VARCHAR(300) DEFAULT NULL,
  notas TEXT,
  fecha_registro TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- 3. Tabla: productos
CREATE TABLE productos (
  id SERIAL PRIMARY KEY,
  nombre VARCHAR(200) NOT NULL,
  descripcion TEXT,
  precio NUMERIC(12,2) NOT NULL DEFAULT 0.00,
  tipo VARCHAR(50) DEFAULT 'sesion',
  categoria VARCHAR(100) DEFAULT NULL,
  estado VARCHAR(20) DEFAULT 'activo',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- 4. Tabla: citas
CREATE TABLE citas (
  id SERIAL PRIMARY KEY,
  cliente_id INTEGER NOT NULL REFERENCES clientes(id) ON DELETE CASCADE,
  producto_id INTEGER DEFAULT NULL REFERENCES productos(id) ON DELETE SET NULL,
  fecha DATE NOT NULL,
  hora TIME DEFAULT NULL,
  duracion_min INTEGER DEFAULT 60,
  estado VARCHAR(30) DEFAULT 'programada',
  observaciones TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- 5. Tabla: sesiones
CREATE TABLE sesiones (
  id SERIAL PRIMARY KEY,
  cliente_id INTEGER NOT NULL REFERENCES clientes(id) ON DELETE CASCADE,
  cita_id INTEGER DEFAULT NULL REFERENCES citas(id) ON DELETE SET NULL,
  producto_id INTEGER DEFAULT NULL REFERENCES productos(id) ON DELETE SET NULL,
  fecha_sesion DATE NOT NULL,
  hora_sesion TIME DEFAULT NULL,
  total NUMERIC(12,2) NOT NULL DEFAULT 0.00,
  abono NUMERIC(12,2) NOT NULL DEFAULT 0.00,
  saldo NUMERIC(12,2) GENERATED ALWAYS AS (total - abono) STORED,
  estado_pago VARCHAR(30) DEFAULT 'pendiente',
  estado_entrega VARCHAR(30) DEFAULT 'pendiente',
  notas TEXT,
  metodo_pago VARCHAR(50) DEFAULT 'efectivo',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- 6. Tabla: facturas
CREATE TABLE facturas (
  id SERIAL PRIMARY KEY,
  sesion_id INTEGER DEFAULT NULL REFERENCES sesiones(id) ON DELETE SET NULL,
  cliente_id INTEGER NOT NULL REFERENCES clientes(id) ON DELETE CASCADE,
  numero_factura VARCHAR(30) NOT NULL,
  total NUMERIC(12,2) NOT NULL DEFAULT 0.00,
  abono NUMERIC(12,2) NOT NULL DEFAULT 0.00,
  metodo_pago VARCHAR(50) DEFAULT 'efectivo',
  estado VARCHAR(30) DEFAULT 'pendiente',
  fecha_emision TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  fecha_vencimiento DATE DEFAULT NULL,
  notas TEXT,
  saldo NUMERIC(12,2) GENERATED ALWAYS AS (total - abono) STORED
);

-- 7. Tabla: ingresos
CREATE TABLE ingresos (
  id SERIAL PRIMARY KEY,
  factura_id INTEGER DEFAULT NULL REFERENCES facturas(id) ON DELETE SET NULL,
  sesion_id INTEGER DEFAULT NULL REFERENCES sesiones(id) ON DELETE SET NULL,
  cliente_id INTEGER DEFAULT NULL REFERENCES clientes(id) ON DELETE SET NULL,
  concepto VARCHAR(300) NOT NULL,
  monto NUMERIC(12,2) NOT NULL DEFAULT 0.00,
  tipo VARCHAR(30) DEFAULT 'ingreso',
  metodo_pago VARCHAR(50) DEFAULT 'efectivo',
  fecha DATE NOT NULL,
  notas TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- 8. Tabla: sesion_fotos
CREATE TABLE sesion_fotos (
  id SERIAL PRIMARY KEY,
  sesion_id INTEGER NOT NULL REFERENCES sesiones(id) ON DELETE CASCADE,
  categoria VARCHAR(100) NOT NULL DEFAULT 'sesion',
  grupo_desc VARCHAR(255) DEFAULT NULL,
  archivo VARCHAR(300) NOT NULL,
  descripcion TEXT,
  fecha_subida TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- 9. Tabla: sesion_productos
CREATE TABLE sesion_productos (
  id SERIAL PRIMARY KEY,
  sesion_id INTEGER NOT NULL REFERENCES sesiones(id) ON DELETE CASCADE,
  producto_id INTEGER NOT NULL REFERENCES productos(id) ON DELETE RESTRICT,
  cantidad INTEGER NOT NULL DEFAULT 1,
  precio NUMERIC(12,2) NOT NULL DEFAULT 0.00
);

-- ============================================================================
-- VOLCADO DE DATOS EN ORDEN DE RELACIONES (PADRES -> HIJOS)
-- ============================================================================



















-- ============================================================================
-- ACTUALIZAR SECUENCIAS AUTO_INCREMENT (SERIAL) EN POSTGRESQL
-- ============================================================================
SELECT setval(pg_get_serial_sequence('usuarios', 'id'), COALESCE((SELECT MAX(id) FROM usuarios), 1));
SELECT setval(pg_get_serial_sequence('clientes', 'id'), COALESCE((SELECT MAX(id) FROM clientes), 1));
SELECT setval(pg_get_serial_sequence('productos', 'id'), COALESCE((SELECT MAX(id) FROM productos), 1));
SELECT setval(pg_get_serial_sequence('citas', 'id'), COALESCE((SELECT MAX(id) FROM citas), 1));
SELECT setval(pg_get_serial_sequence('sesiones', 'id'), COALESCE((SELECT MAX(id) FROM sesiones), 1));
SELECT setval(pg_get_serial_sequence('facturas', 'id'), COALESCE((SELECT MAX(id) FROM facturas), 1));
SELECT setval(pg_get_serial_sequence('ingresos', 'id'), COALESCE((SELECT MAX(id) FROM ingresos), 1));
SELECT setval(pg_get_serial_sequence('sesion_fotos', 'id'), COALESCE((SELECT MAX(id) FROM sesion_fotos), 1));
SELECT setval(pg_get_serial_sequence('sesion_productos', 'id'), COALESCE((SELECT MAX(id) FROM sesion_productos), 1));

COMMIT;
